 [RuntimeInitializeOnLoadMethod]static void Boot(){if(Array.IndexOf(Environment.GetCommandLineArgs(),"-tsProductionTour")<0)return;var g=new GameObject("Owned explicit build scene and window presentation tour");DontDestroyOnLoad(g);if(!SportsProbeInputIsolation.Active)g.AddComponent<SportsProbeInputIsolation>();g.AddComponent<SportsProductionTour>();}
 string folder;int errors,events,scenes;bool restored;readonly StringBuilder log=new StringBuilder();readonly Dictionary<string,string> prefs=new Dictionary<string,string>();readonly HashSet<string> had=new HashSet<string>();
