 IEnumerator Start(){folder=SportsEvidencePaths.Folder("ProductionTourEvidence");File.WriteAllText(folder+"/result.txt","RUNNING "+DateTime.UtcNow.ToString("O"));Application.logMessageReceived+=Error;Check(!Application.isEditor&&SceneManager.sceneCountInBuildSettings==33,"real Windows build has exactly33 explicit Sports scenes");if(Application.isEditor)yield break;for(int index=1;index<SceneManager.sceneCountInBuildSettings;index++){var scene=Path.GetFileNameWithoutExtension(SceneUtility.GetScenePathByBuildIndex(index));SportsNavigation.LoadSport(scene);yield return null;yield return null;yield return new WaitForSecondsRealtime(.15f);scenes++;Check(SceneManager.GetActiveScene().name==scene&&FindObjectsByType<AudioListener>().Length==1,scene+" explicit scene loads with one listener");bool missing=false;foreach(var root in SceneManager.GetActiveScene().GetRootGameObjects())foreach(var component in root.GetComponentsInChildren<MonoBehaviour>(true))missing|=component==null;Check(!missing,scene+" no missing runtime scripts");var m=FindAnyObjectByType<SportsEventSession>();if(m!=null){events++;if(!prefs.ContainsKey(m.PreferenceKey)){if(SportsPrefs.HasKey(m.PreferenceKey))had.Add(m.PreferenceKey);prefs[m.PreferenceKey]=SportsPrefs.GetString(m.PreferenceKey);}m.SetupScreen();m.setup.count=m.MaximumPlayers;if(m.TeamSport)m.teamA=m.teamB=4;m.NormalizeSetup();m.AllBots();for(int i=0;i<m.setup.count;i++)m.setup.players[i].name="Long Participant Name "+(i+1);Check(m.StartMatch(),scene+" maximum autonomous participant setup starts");yield return new WaitForSecondsRealtime(.35f);m.Pause();m.menus.Show(SportsEventScreen.Play);foreach(var size in new[]{new Vector2Int(1280,720),new Vector2Int(1920,1080),new Vector2Int(1440,900),new Vector2Int(1280,960),new Vector2Int(2560,1080)}){Screen.SetResolution(size.x,size.y,false);yield return new WaitForSecondsRealtime(.25f);ScreenCapture.CaptureScreenshot(folder+"/"+scene+"-"+size.x+"x"+size.y+"-window.png");yield return new WaitForSecondsRealtime(.1f);Check(Screen.width==size.x&&Screen.height==size.y,scene+" actual player window size "+size);var corners=new Vector3[4];bool inside=true;foreach(var text in new[]{m.menus.header,m.menus.status})if(text!=null&&text.gameObject.activeInHierarchy){text.rectTransform.GetWorldCorners(corners);foreach(var p in corners){var v=RectTransformUtility.WorldToScreenPoint(null,p);inside&=v.x>=-2&&v.x<=Screen.width+2&&v.y>=-2&&v.y<=Screen.height+2;}}Check(inside,scene+" critical header/status fit actual window "+size);}m.menus.Show(SportsEventScreen.Pause);m.Resume();yield return null;Check(m.Live||m.Finished,scene+" pause returns to live state");m.SetupScreen();Check(m.StartMatch(),scene+" repeated rematch starts");yield return null;m.SetupScreen();}SportsNavigation.FrontEnd();yield return null;yield return null;Check(FindAnyObjectByType<SportsFrontEnd>()!=null&&FindObjectsByType<AudioListener>().Length==1,scene+" repeated return cleans cameras/audio");int enabledCameras=0;foreach(var camera in FindObjectsByType<Camera>())if(camera.enabled&&camera.gameObject.activeInHierarchy)enabledCameras++;Check(enabledCameras<=2&&FindObjectsByType<SportsEventSession>().Length==0&&FindObjectsByType<SportsWaterInteraction>().Length==0&&FindObjectsByType<SportsSnowSurface>().Length==0&&FindObjectsByType<SportsCabLook>().Length==0,scene+" no orphaned sport, effect or cab camera owners; active cameras="+enabledCameras);}Screen.SetResolution(1280,720,false);yield return new WaitForSecondsRealtime(.25f);var front=FindAnyObjectByType<SportsFrontEnd>();Check(front.catalogue.cards.Length==30,"normal catalogue has30 sports; Wallball remains explicit experimental Scrap Heap entry");front.Action("scrapheap");yield return new WaitForSecondsRealtime(.2f);ScreenCapture.CaptureScreenshot(folder+"/scrap-heap-window.png");Check(front.Page==4,"experimental menu is reachable manually");Check(scenes==32&&events>=20,"all32 non-front saved scenes visited; event presentation samples="+events);Restore();log.AppendLine("ERRORS="+errors+". Actual Windows scene loading, normal overlay screenshots at five real window sizes, maximum AI rosters, pause/rematch/menu cycles. No human/controller playtest or claim that a brief tour replaces full physical matches.");File.WriteAllText(folder+"/result.txt",log.ToString());Application.Quit(errors==0?0:2);}
 void Restore(){if(restored)return;restored=true;Application.logMessageReceived-=Error;foreach(var p in prefs)if(had.Contains(p.Key))SportsPrefs.SetString(p.Key,p.Value);else SportsPrefs.DeleteKey(p.Key);SportsPrefs.Save();Time.timeScale=1;}void OnDestroy(){Restore();}
